//! Mapping-provider Feed — live segment speeds from a mapping API
//! (MapmyIndia / Google-style traffic tiles) for the corridor network.
//!
//! The road network itself is no longer fetched at runtime: it is compiled
//! in from corridor.road_segments (segments_ahmedabad.rs, generated by
//! scripts/gen_ingress_segments.py). In edge-deployment mode this collector
//! emulates the provider's 5-minute segment-speed snapshot for every seeded
//! Ahmedabad segment: the shared city congestion field (city.rs) seen
//! through the provider's smoothing (±5%), placed at each segment midpoint.
//! Rows are labelled `DataQuality::Synthetic`.
//!
//! (An earlier version emitted the free-flow speed limit with congestion 0
//! as a "topology heartbeat"; downstream that read as a fully clear road at
//! rush hour and tripped the speed-jump check by design.)

use chrono::{DateTime, Utc};
use tokio::sync::mpsc;
use tracing::instrument;

use super::city::{CongestionField, congestion_for, segments};
use super::rng::Lcg;
use crate::{DataQuality, FeedSource, IngressError, TrafficObservation};

/// Seconds between provider snapshots.
pub const REFRESH_SEC: u64 = 300;

/// Relative error of the provider's smoothed speed (1 sigma).
const PROVIDER_SPEED_ERROR: f64 = 0.05;

/// Emulated mapping-provider live-speed snapshots.
pub struct MappingFeed {
    field: CongestionField,
    rng: Lcg,
}

impl MappingFeed {
    pub fn new(field: CongestionField, seed: u64) -> Self {
        Self {
            field,
            rng: Lcg::new(seed),
        }
    }

    /// One snapshot covering every corridor segment at instant `t`.
    pub fn snapshot(&mut self, t: DateTime<Utc>) -> Vec<TrafficObservation> {
        segments()
            .iter()
            .map(|seg| {
                let truth = self.field.speed(seg, t) as f64;
                let speed = (truth * (1.0 + PROVIDER_SPEED_ERROR * self.rng.gaussian()))
                    .clamp(3.0, 1.1 * seg.speed_limit_kmh as f64)
                    as f32;
                TrafficObservation {
                    timestamp_ms: t.timestamp_millis(),
                    lon: seg.mid.0,
                    lat: seg.mid.1,
                    segment_id: seg.id.to_string(),
                    speed_kmh: speed,
                    congestion_index: congestion_for(seg.speed_limit_kmh, speed),
                    source: FeedSource::MappingApi,
                    data_quality: DataQuality::Synthetic,
                    confidence: 0.8,
                }
            })
            .collect()
    }
}

/// Periodically emits the provider's live segment speeds for all corridor
/// segments (first snapshot immediately at start-up).
///
/// Interval: 5 minutes (provider traffic tiles refresh on that order).
#[instrument(name = "mapping_api_fetcher", skip(tx))]
pub async fn fetch_road_network_updates(
    tx: mpsc::Sender<TrafficObservation>,
) -> Result<(), IngressError> {
    tracing::info!(
        segments = segments().len(),
        interval_sec = REFRESH_SEC,
        "mapping-provider speed feed initialized — Ahmedabad network, edge synthetic mode"
    );

    let mut feed = MappingFeed::new(
        CongestionField::from_env(),
        Utc::now().timestamp_millis() as u64 ^ 0x0A11_CE55,
    );

    loop {
        for obs in feed.snapshot(Utc::now()) {
            if tx.send(obs).await.is_err() {
                tracing::error!("feed channel closed — shutting down mapping updater");
                return Err(IngressError::ChannelSend);
            }
        }

        tracing::debug!(
            segments = segments().len(),
            "mapping-provider snapshot complete"
        );

        tokio::time::sleep(std::time::Duration::from_secs(REFRESH_SEC)).await;
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::feeds::city::DEFAULT_CITY_SEED;

    #[test]
    fn snapshot_covers_every_segment_at_its_midpoint() {
        let mut feed = MappingFeed::new(CongestionField::new(DEFAULT_CITY_SEED), 4);
        let rows = feed.snapshot(Utc::now());
        assert_eq!(rows.len(), segments().len());
        for (row, seg) in rows.iter().zip(segments()) {
            assert_eq!(row.segment_id, seg.id.to_string());
            assert_eq!((row.lon, row.lat), seg.mid);
            assert!(row.speed_kmh >= 3.0 && row.speed_kmh <= 1.1 * seg.speed_limit_kmh);
            assert_eq!(row.data_quality, DataQuality::Synthetic);
        }
    }
}
